<script setup lang="ts">
import { ref } from 'vue'
import { ElMessage } from 'element-plus'
import type { ColumnProfile, DiskRule, LogicalField, TypedScalar } from '../types'
import { diskRule, diskRuleLabels, diskSingleTypes, diskTypeLabels, roundings } from '../diskRules'
import TypedScalarInput from './TypedScalarInput.vue'
const props = defineProps<{ modelValue: DiskRule[]; fields: LogicalField[]; bindings: Record<string, string>; columns: ColumnProfile[] }>()
const emit = defineEmits<{ 'update:modelValue': [value: DiskRule[]]; 'update:fields': [value: LogicalField[]]; 'update:bindings': [value: Record<string, string>] }>()
const json = ref('')
const jsonOpen = ref(false)
const operators = { eq: '等于', ne: '不等于', gt: '大于', gte: '大于等于', lt: '小于', lte: '小于等于', contains: '包含', starts_with: '开头为', ends_with: '结尾为' }
function update(index: number, patch: Partial<DiskRule>) { emit('update:modelValue', props.modelValue.map((rule, i) => i === index ? { ...rule, ...patch } : rule)) }
function changeType(index: number, type: DiskRule['type']) { emit('update:modelValue', props.modelValue.map((rule, i) => i === index ? { ...diskRule(type), id: rule.id, enabled: rule.enabled } : rule)) }
function move(index: number, by: number) { const next = [...props.modelValue]; const [rule] = next.splice(index, 1); if (rule) next.splice(index + by, 0, rule); emit('update:modelValue', next) }
function copy(index: number) { const next = [...props.modelValue]; next.splice(index + 1, 0, { ...JSON.parse(JSON.stringify(next[index])), id: crypto.randomUUID() }); emit('update:modelValue', next) }
function binding(id: string, value: string) { emit('update:bindings', { ...props.bindings, [id]: value }) }
function addField() { emit('update:fields', [...props.fields, { id: `field_${crypto.randomUUID().slice(0, 8)}`, label: '新字段' }]) }
function values(index: number, key: 'values' | 'markers', at: number, value: TypedScalar) { const list = [...(props.modelValue[index]![key] || [])]; list[at] = value; update(index, { [key]: list }) }
function importJson() {
  try {
    const parsed = JSON.parse(json.value)
    if (parsed.schemaVersion !== 3 || parsed.engineVersion !== 'v3-disk' || !Array.isArray(parsed.rules) || !Array.isArray(parsed.logicalFields)) throw new Error('需包含 schemaVersion:3、engineVersion:v3-disk、logicalFields 和 rules。')
    emit('update:fields', parsed.logicalFields); emit('update:modelValue', parsed.rules)
    emit('update:bindings', parsed.fieldBindings || {})
    jsonOpen.value = false; ElMessage.success('规则草稿已载入；保存和提交时仍会校验。')
  } catch (e) { ElMessage.error(e instanceof Error ? e.message : 'JSON 格式无效。') }
}
function exportJson() { json.value = JSON.stringify({ schemaVersion: 3, engineVersion: 'v3-disk', logicalFields: props.fields, rules: props.modelValue, fieldBindings: props.bindings }, null, 2); jsonOpen.value = true }
</script>
<template>
  <div class="rule-editor disk-rule-editor">
    <el-alert title="严格按启用规则的配置顺序执行；逻辑字段需绑定到当前文件列。保存与提交均由服务端校验。" type="info" :closable="false" class="panel-alert" />
    <div class="editor-tools"><el-button size="small" @click="exportJson">导入 / 导出规则 JSON</el-button><el-tag>schema 3 · v3-disk</el-tag></div>
    <el-collapse class="logical-fields"><el-collapse-item title="逻辑字段与当前文件绑定" name="bindings"><p class="form-note">字段 ID 随规则版本保存；绑定随任务冻结。更换文件后请重新检查绑定。</p><div v-for="(field, index) in fields" :key="field.id" class="binding-row"><span class="mono">{{ field.id }}</span><el-input :model-value="field.label" aria-label="逻辑字段名称" @update:model-value="emit('update:fields', fields.map((item, i) => i === index ? { ...item, label: $event } : item))" /><el-select :model-value="bindings[field.id] || ''" clearable :aria-label="`${field.label}绑定列`" placeholder="选择输入列" @update:model-value="binding(field.id, $event)"><el-option v-for="column in columns" :key="column.id || column.name" :value="column.id || column.name" :label="`${column.name} · ${column.id}`" /></el-select><el-button text type="danger" @click="emit('update:fields', fields.filter((_, i) => i !== index))">移除字段</el-button></div><el-button size="small" @click="addField">添加逻辑字段</el-button></el-collapse-item></el-collapse>
    <el-empty v-if="!modelValue.length" description="添加规则；空规则集仍可转换格式并生成报告。" />
    <article v-for="(rule, index) in modelValue" :key="rule.id" class="rule-row" :class="{ 'disabled-rule': !rule.enabled }">
      <div class="rule-row-heading"><span class="rule-number">{{ String(index + 1).padStart(2, '0') }}</span><el-select :model-value="rule.type" class="rule-type" aria-label="规则类型" @update:model-value="changeType(index, $event)"><el-option v-for="(label, type) in diskRuleLabels" :key="type" :value="type" :label="label" /></el-select><el-switch :model-value="rule.enabled" :aria-label="`启用第 ${index + 1} 条规则`" @update:model-value="update(index, { enabled: Boolean($event) })" /><div class="rule-controls"><el-button size="small" :disabled="index === 0" :aria-label="`上移第 ${index + 1} 条规则`" @click="move(index, -1)">↑</el-button><el-button size="small" :disabled="index === modelValue.length - 1" :aria-label="`下移第 ${index + 1} 条规则`" @click="move(index, 1)">↓</el-button><el-button size="small" @click="copy(index)">复制</el-button><el-button size="small" text type="danger" @click="emit('update:modelValue', modelValue.filter((_, i) => i !== index))">移除</el-button></div></div>
      <div class="rule-phase"><span>{{ rule.id }}</span>{{ rule.enabled ? '按配置顺序执行' : '已停用，报告标记为 DISABLED' }}</div>
      <div class="rule-fields">
        <template v-if="rule.type === 'compare_fields'"><label class="field"><span>左侧字段</span><el-select :model-value="rule.leftFieldId" aria-label="左侧字段" @update:model-value="update(index, { leftFieldId: $event })"><el-option v-for="field in fields" :key="field.id" :value="field.id" :label="field.label" /></el-select></label><label class="field"><span>右侧字段</span><el-select :model-value="rule.rightFieldId" aria-label="右侧字段" @update:model-value="update(index, { rightFieldId: $event })"><el-option v-for="field in fields" :key="field.id" :value="field.id" :label="field.label" /></el-select></label><label class="field"><span>比较类型</span><el-select :model-value="rule.valueType" @update:model-value="update(index, { valueType: $event, ...($event === 'boolean' ? { operator: 'eq' } : {}) })"><el-option v-for="(label, type) in diskTypeLabels" :key="type" :value="type" :label="label" /></el-select></label><label class="field"><span>空值策略</span><el-select :model-value="rule.nullPolicy" @update:model-value="update(index, { nullPolicy: $event })"><el-option value="violation" label="空值视为违规" /><el-option value="skip" label="跳过空值" /></el-select></label></template>
        <label v-else class="field full-field"><span>{{ diskSingleTypes.includes(rule.type) ? '目标逻辑字段' : rule.type === 'deduplicate' ? '判重字段（留空 = 整行）' : '应用逻辑字段' }}</span><el-select v-if="diskSingleTypes.includes(rule.type)" :model-value="rule.fieldId" aria-label="目标列" @update:model-value="update(index, { fieldId: $event })"><el-option v-for="field in fields" :key="field.id" :value="field.id" :label="field.label" /></el-select><el-select v-else :model-value="rule.fieldIds || []" multiple aria-label="应用列" @update:model-value="update(index, { fieldIds: $event })"><el-option v-for="field in fields" :key="field.id" :value="field.id" :label="field.label" /></el-select></label>
        <label v-if="['cast', 'validate_type'].includes(rule.type)" class="field"><span>数据类型</span><el-select :model-value="rule.dtype" aria-label="数据类型" @update:model-value="update(index, { dtype: $event, dateFormat: undefined, outputFormat: undefined, ...($event === 'decimal' ? { precision: 38, scale: 2, rounding: 'HALF_UP' } : { precision: undefined, scale: undefined, rounding: undefined }) })"><el-option v-for="(label, type) in diskTypeLabels" :key="type" :value="type" :label="label" /></el-select></label>
        <template v-if="rule.dtype === 'decimal' || rule.type === 'fill_stat'"><label class="field"><span>小数位 scale</span><el-input-number :model-value="rule.scale ?? 2" :min="0" :max="12" :precision="0" :controls="false" aria-label="Decimal小数位" @update:model-value="update(index, { scale: $event })" /></label><label class="field"><span>舍入方式</span><el-select :model-value="rule.rounding || 'HALF_UP'" aria-label="舍入方式" @update:model-value="update(index, { rounding: $event })"><el-option v-for="rounding in roundings" :key="rounding" :value="rounding" :label="rounding" /></el-select></label></template>
        <label v-if="rule.type === 'case'" class="field"><span>大小写</span><el-select :model-value="rule.mode" @update:model-value="update(index, { mode: $event })"><el-option value="lower" label="小写" /><el-option value="upper" label="大写" /></el-select></label>
        <template v-if="rule.type === 'replace'"><label class="field"><span>查找文本</span><el-input :model-value="rule.search" aria-label="查找文本" @update:model-value="update(index, { search: $event })" /></label><label class="field"><span>替换文本</span><el-input :model-value="rule.replacement" aria-label="替换文本" @update:model-value="update(index, { replacement: $event })" /></label><label class="field"><span>替换次数（0 = 全部）</span><el-input-number :model-value="rule.count || 0" :min="0" :precision="0" :controls="false" @update:model-value="update(index, { count: $event })" /></label></template>
        <label v-if="rule.type === 'fill_null' || rule.type === 'compare' || rule.type === 'fill_stat' && rule.emptyPolicy === 'constant'" class="field full-field"><span>类型化常量</span><TypedScalarInput :model-value="rule.value" @update:model-value="update(index, { value: $event })" /></label>
        <div v-if="rule.type === 'enum' || rule.type === 'missing'" class="field full-field"><span>{{ rule.type === 'enum' ? '允许值' : '缺失标记' }}</span><div v-for="(value, at) in (rule.type === 'enum' ? rule.values : rule.markers) || []" :key="at" class="scalar-list-row"><TypedScalarInput :model-value="value" @update:model-value="values(index, rule.type === 'enum' ? 'values' : 'markers', at, $event)" /><el-button text type="danger" @click="update(index, { [rule.type === 'enum' ? 'values' : 'markers']: (rule.type === 'enum' ? rule.values : rule.markers)!.filter((_, i) => i !== at) })">移除</el-button></div><el-button size="small" @click="update(index, { [rule.type === 'enum' ? 'values' : 'markers']: [...((rule.type === 'enum' ? rule.values : rule.markers) || []), { type: 'string', value: '' }] })">添加值</el-button></div>
        <template v-if="['range', 'length'].includes(rule.type)"><label class="field"><span>下界（可空）</span><el-input :model-value="String(rule.min ?? '')" aria-label="规则下界" @update:model-value="update(index, { min: $event === '' ? undefined : rule.type === 'length' ? Number($event) : $event })" /></label><label class="field"><span>上界（可空）</span><el-input :model-value="String(rule.max ?? '')" aria-label="规则上界" @update:model-value="update(index, { max: $event === '' ? undefined : rule.type === 'length' ? Number($event) : $event })" /></label><el-checkbox v-if="rule.type === 'range'" :model-value="rule.inclusiveMin !== false" @update:model-value="update(index, { inclusiveMin: Boolean($event) })">包含下界</el-checkbox><el-checkbox v-if="rule.type === 'range'" :model-value="rule.inclusiveMax !== false" @update:model-value="update(index, { inclusiveMax: Boolean($event) })">包含上界</el-checkbox></template>
        <label v-if="rule.type === 'iqr'" class="field"><span>IQR 系数</span><el-input :model-value="String(rule.factor ?? '1.5')" @update:model-value="update(index, { factor: $event })" /></label>
        <label v-if="rule.type === 'fill_stat'" class="field"><span>统计策略</span><el-select :model-value="rule.strategy" @update:model-value="update(index, { strategy: $event })"><el-option value="mean" label="均值" /><el-option value="median" label="中位数" /><el-option value="mode" label="众数" /></el-select></label>
        <label v-if="['fill_stat', 'iqr'].includes(rule.type)" class="field"><span>无有效值时</span><el-select :model-value="rule.emptyPolicy" @update:model-value="update(index, { emptyPolicy: $event, value: $event === 'constant' ? { type: 'string', value: '' } : undefined })"><el-option value="fail" label="任务失败" /><el-option value="leave" label="保留原值" /><el-option v-if="rule.type === 'fill_stat'" value="constant" label="指定常量" /></el-select></label>
        <label v-if="rule.type === 'deduplicate'" class="field"><span>保留方式</span><el-select :model-value="rule.keep" @update:model-value="update(index, { keep: $event })"><el-option value="first" label="原始顺序第一条" /><el-option value="last" label="原始顺序最后一条" /></el-select></label>
        <label v-if="['compare', 'compare_fields'].includes(rule.type)" class="field"><span>比较运算</span><el-select :model-value="rule.operator" @update:model-value="update(index, { operator: $event })"><el-option v-for="(label, op) in operators" :key="op" :value="op" :label="label" :disabled="rule.type === 'compare_fields' && (['contains', 'starts_with', 'ends_with'].includes(op) || rule.valueType === 'boolean' && !['eq', 'ne'].includes(op))" /></el-select></label>
        <label v-if="rule.type === 'regex'" class="field full-field"><span>正则表达式</span><el-input :model-value="rule.pattern" maxlength="256" @update:model-value="update(index, { pattern: $event })" /></label><label v-if="rule.type === 'rename'" class="field"><span>新的列名</span><el-input :model-value="rule.target" placeholder="输入最终列名" @update:model-value="update(index, { target: $event })" /></label>
        <template v-if="rule.dtype === 'datetime'"><label class="field"><span>输入日期格式</span><el-input :model-value="rule.dateFormat" placeholder="iso8601" @update:model-value="update(index, { dateFormat: $event || undefined })" /></label><label v-if="rule.type === 'cast'" class="field"><span>输出日期格式</span><el-input :model-value="rule.outputFormat" placeholder="iso8601" @update:model-value="update(index, { outputFormat: $event || undefined })" /></label></template>
        <label v-if="rule.onError" class="field full-field"><span>失败处理</span><el-select :model-value="rule.onError" aria-label="失败处理策略" @update:model-value="update(index, { onError: $event })"><el-option value="drop" label="移除整行，并记录违规明细" /><el-option value="mark" label="保留整行，附带质量标记和全部违规" /><el-option value="fail" label="任务失败，并记录规则、字段和原因" /><el-option v-if="['cast', 'range', 'iqr'].includes(rule.type)" value="null" label="失败字段置空，记录违规明细" /></el-select></label>
      </div>
    </article>
    <el-button class="add-rule" :disabled="modelValue.length >= 50" @click="emit('update:modelValue', [...modelValue, diskRule()])">＋ 添加清洗规则 <span class="muted">{{ modelValue.length }}/50</span></el-button>
    <el-dialog v-model="jsonOpen" title="新版规则 JSON" width="min(92vw, 800px)"><p>导入会替换当前草稿。仅接收 schema 3 / v3-disk，历史规则请先使用显式转换。</p><el-input v-model="json" type="textarea" :rows="18" aria-label="规则JSON" /><template #footer><el-button @click="jsonOpen = false">返回</el-button><el-button type="primary" @click="importJson">载入当前草稿</el-button></template></el-dialog>
  </div>
</template>
